<body>  <div class="container">  <h1>Purchase Orders Tab Verification</h1>  <p class="subtitle">Visual verification of what admin will see in Merchandise and Fuel tabs</p>  <div class="status-card">  <h2 style="margin-bottom: 15px; color: #002F6C;">Summary</h2>  <div class="status-grid">  <div class="stat-box merch">  <div class="stat-number"><?= count($merch_pos) ?></div>  <div class="stat-label">Merchandise POs</div>  </div>  <div class="stat-box fuel">  <div class="stat-number"><?= count($fuel_pos) ?></div>  <div class="stat-label">Fuel POs</div>  </div>  <div class="stat-box">  <div class="stat-number"><?= count($merch_pos) + count($fuel_pos) ?></div>  <div class="stat-label">Total POs</div>  </div>  </div>  <?php if (count($merch_pos) >= 12 && count($fuel_pos) >= 4): ?>  <p class="success">PERFECT! Admin will see 12 merchandise + 4 fuel = 16 total individual POs</p>  <?php else: ?>  <p class="warning">Expected 12 merchandise + 4 fuel, but found <?= count($merch_pos) ?> merchandise + <?= count($fuel_pos) ?> fuel</p>  <?php endif; ?>  </div>  <div class="tabs">  <button class="tab-btn active" onclick="switchTab('merch')">  Merchandise (<?= count($merch_pos) ?>)  </button>  <button class="tab-btn" onclick="switchTab('fuel')">  Fuel (<?= count($fuel_pos) ?>)  </button>  </div>  <!-- MERCHANDISE TAB -->  <div class="tab-content active" id="tab-merch">  <div class="status-card">  <h3 style="margin-bottom: 15px; color: #002F6C;"> Merchandise Purchase Orders</h3>  <?php if (empty($merch_pos)): ?>  <p style="text-align:center; padding:40px; color:#94a3b8;">No merchandise purchase orders found.</p>  <?php else: ?>  <table>  <thead>  <tr>  <th>PO Number</th>  <th>Product Name</th>  <th>Quantity</th>  <th>Unit Price</th>  <th>Total Amount</th>  <th>Status</th>  <th>Created By</th>  <th>Date</th>  </tr>  </thead>  <tbody>  <?php foreach ($merch_pos as $po): ?>  <tr>  <td class="po-number"><?= htmlspecialchars($po['po_no']) ?></td>  <td><?= htmlspecialchars($po['product_name']) ?></td>  <td><?= number_format($po['quantity'], 0) ?> pcs</td>  <td>₱<?= number_format($po['unit_price'], 2) ?></td>  <td style="font-weight:700;">₱<?= number_format($po['total_amount'], 2) ?></td>  <td>  <span class="badge badge-pending"><?= htmlspecialchars($po['status']) ?></span>  </td>  <td><?= htmlspecialchars($po['created_by']) ?></td>  <td><?= date('M d, Y h:i A', strtotime($po['created_at'])) ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  <?php endif; ?>  </div>  </div>  <!-- FUEL TAB -->  <div class="tab-content" id="tab-fuel">  <div class="status-card">  <h3 style="margin-bottom: 15px; color: #002F6C;"> Fuel Purchase Orders</h3>  <?php if (empty($fuel_pos)): ?>  <p style="text-align:center; padding:40px; color:#94a3b8;">No fuel purchase orders found.</p>  <?php else: ?>  <table>  <thead>  <tr>  <th>PO Number</th>  <th>Fuel Type</th>  <th>Volume</th>  <th>Unit Price</th>  <th>Total Amount</th>  <th>Status</th>  <th>Created By</th>  <th>Date</th>  </tr>  </thead>  <tbody>  <?php foreach ($fuel_pos as $po): ?>  <tr>  <td class="po-number"><?= htmlspecialchars($po['po_no']) ?></td>  <td><?= htmlspecialchars($po['fuel_name']) ?></td>  <td><?= number_format($po['volume'], 2) ?> L</td>  <td>₱<?= number_format($po['unit_price'], 2) ?></td>  <td style="font-weight:700;">₱<?= number_format($po['total_amount'], 2) ?></td>  <td>  <span class="badge badge-pending"><?= htmlspecialchars($po['status']) ?></span>  </td>  <td><?= htmlspecialchars($po['created_by']) ?></td>  <td><?= date('M d, Y h:i A', strtotime($po['created_at'])) ?></td>  </tr>  <?php endforeach; ?>  </tbody>  </table>  <?php endif; ?>  </div>  </div>  <div class="status-card" style="margin-top: 30px;">  <h3 style="margin-bottom: 10px; color: #002F6C;">Notes</h3>  <ul style="line-height: 2; color: #475569;">  <li><strong>Each row</strong> represents one individual purchase order</li>  <li><strong>Merchandise Tab</strong> shows individual product items with quantities in pieces (pcs)</li>  <li><strong>Fuel Tab</strong> shows individual fuel types with volumes in liters (L)</li>  <li><strong>Admin can finalize/reject</strong> each PO individually from the actual page</li>  <li><strong>This verification page</strong> confirms the fix is working correctly</li>  </ul>  </div>  <div style="text-align: center; margin-top: 30px; padding: 20px;">  <a href="public/admin_purchase_orders.php" style="background: #002F6C; color: white; padding: 12px 24px; text-decoration: none; border-radius: 8px; font-weight: 600;">  → Go to Actual Purchase Orders Page  </a>  </div>  </div>  <script>  function switchTab(tab) {  // Update tab buttons  document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));  event.target.classList.add('active');  // Update tab content  document.querySelectorAll('.tab-content').forEach(content => content.classList.remove('active'));  document.getElementById('tab-' + tab).classList.add('active');  }  </script>
